                  id="profile-timezone"
                  size="l"
                  width="max"
                  filterable
                  filterPlaceholder="Поиск по названию"
                  options={TIMEZONE_OPTIONS}
                  value={[form.timezone]}
                  onUpdate={(values) => update('timezone', values[0] ?? form.timezone)}
                  placeholder="Выберите часовой пояс"
                />
              </Field>
